import type { SVGProps } from "react";

/**
 * InterCat Lynx logo mark (lynx head, front view).
 *
 * Drawn with `currentColor`, so it follows the surrounding text colour and
 * works in the light and the dark theme. The geometry is the same as in
 * docs/assets/logo (generated by build_logo.py).
 *
 * - variant "line": thin line art, for large display (hero, about page)
 * - variant "bold": heavier strokes and a simplified face, for sizes below
 *   about 64 px (navigation, favicon)
 *
 * Only the left half of the head is described; the right half is the same
 * group mirrored. No ids or <use> are needed, so the mark can appear several
 * times on one page without clashes.
 */

const OUTLINE =
  "M256 124 Q232 122 210 132 L188 56 L126 154 Q100 192 94 226 L72 270 L100 264 L80 322 L110 306 L98 376 L140 344 Q176 388 214 398 Q238 406 256 406";

function LineHalf() {
  return (
    <>
      <path d={OUTLINE} />
      <path d="M160 212 Q196 186 238 216 Q198 240 160 212 Z" />
      <path d="M152 192 Q196 162 244 194" />
      <path d="M156 205 Q138 203 124 215" />
      <path d="M240 138 L244 168 M224 142 L228 164" />
      <g fill="currentColor" stroke="none">
        <path d="M194 62 L180 2 L174 66 Z" />
        <ellipse cx="203" cy="214" rx="6" ry="12" />
      </g>
    </>
  );
}

function BoldHalf() {
  return (
    <>
      <path d={OUTLINE} />
      <path d="M154 206 Q196 188 238 224 Q190 238 154 206 Z" fill="currentColor" />
      <path d="M198 66 L180 -6 L170 70 Z" fill="currentColor" stroke="none" />
    </>
  );
}

export function LynxMark({
  variant = "line",
  ...props
}: { variant?: "line" | "bold" } & SVGProps<SVGSVGElement>) {
  const bold = variant === "bold";
  const Half = bold ? BoldHalf : LineHalf;
  return (
    <svg
      viewBox="-8 -12 528 430"
      fill="none"
      stroke="currentColor"
      strokeWidth={bold ? 18 : 7}
      strokeLinecap="round"
      strokeLinejoin="round"
      role="img"
      aria-label="InterCat Lynx"
      {...props}
    >
      <g>
        <Half />
      </g>
      <g transform="translate(512 0) scale(-1 1)">
        <Half />
      </g>
      <path d="M232 268 Q256 256 280 268 L256 296 Z" />
      {!bold && (
        <path d="M256 152 L256 256 M256 296 L256 314 Q240 338 212 328 M256 314 Q272 338 300 328" />
      )}
    </svg>
  );
}
